import{_ as o,o as a,c as t,a6 as r}from"./chunks/framework.BJFjZBwW.js";const s="/dev/assets/OpenMQTTgateway_ESP32_binary_flash.Cojr_vCp.png",i="/dev/assets/OpenMQTTgateway_ESP32_binary_flash2.q4qF4wss.png",n="/dev/assets/OpenMQTTgateway_NodeMCU_PyFlasher.Cpfui_7y.png",m=JSON.parse('{"title":"(Option 2) Upload ready-to-go binaries","description":"","frontmatter":{},"headers":[],"relativePath":"upload/binaries.md","filePath":"upload/binaries.md","lastUpdated":1750591539000}'),l={name:"upload/binaries.md"};function p(d,e,h,c,f,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="option-2-upload-ready-to-go-binaries" tabindex="-1">(Option 2) Upload ready-to-go binaries <a class="header-anchor" href="#option-2-upload-ready-to-go-binaries" aria-label="Permalink to &quot;(Option 2) Upload ready-to-go binaries&quot;">​</a></h1><p>This section is useful if you want to directly flash your ESP from your desktop. Once flashed you can change wifi and broker settings. Nevertheless you will not be able to change advanced parameters; if you want to do so, refer to <a href="./builds.html">Upload your configurations</a> section.</p><p>Download the binary corresponding to your board and gateway <a href="https://github.com/1technophile/OpenMQTTGateway/releases" target="_blank" rel="noreferrer">here</a> from github and uncompress it.</p><h2 id="esp32" tabindex="-1">ESP32 <a class="header-anchor" href="#esp32" aria-label="Permalink to &quot;ESP32&quot;">​</a></h2><ul><li>Download the bootloader <a href="https://github.com/espressif/arduino-esp32/raw/2.0.5/tools/sdk/esp32/bin/bootloader_dio_80m.bin" target="_blank" rel="noreferrer">here</a></li><li>Download the boot_app0 from <a href="https://github.com/espressif/arduino-esp32/raw/2.0.5/tools/partitions/boot_app0.bin" target="_blank" rel="noreferrer">here</a></li><li>Download the flash tool utility from espressif: <a href="https://www.espressif.com/en/products/hardware/esp32/resources" target="_blank" rel="noreferrer">https://www.espressif.com/en/products/hardware/esp32/resources</a></li><li>Uncompress the package</li><li>Execute <code>flash_download_tools</code></li><li>Choose Developer mode</li><li>Choose ESP32 DownloadTool</li><li>Set the files and the address as below: <img src="'+s+'" alt="Flash download tool"></li><li>Set the config as above</li><li>Connect your ESP32 board and select the COM port</li><li>Click on erase if it is your first upload</li><li>If you see SYNC (above the START button) for more than 5 seconds, press the boot button of your ESP32</li><li>Once done you can click on START button</li><li>If you see SYNC (above the START button) for more than 5 seconds, press the boot button of your ESP32 The upload details appears in the rear shell windows, you can see also the progress bar changing.</li><li>Once done the flash tool display &quot;FINISH&quot; like below <img src="'+i+`" alt="Flash download tool 2"></li></ul><h3 id="linux-esptool-py" tabindex="-1">Linux - esptool.py <a class="header-anchor" href="#linux-esptool-py" aria-label="Permalink to &quot;Linux - esptool.py&quot;">​</a></h3><p>If you want to upload the ready-to-go binary from Linux (or any other OS where you have Python) you can use the <a href="https://github.com/espressif/esptool" target="_blank" rel="noreferrer">esptool.py</a>. This an official Python based flashing tool from Espressif for ESP82XX and ESP32.</p><ul><li><p>Install esptool from PyPI via pip: <code>pip install esptool</code> (or using the python package manager of your choice)</p></li><li><p>Now you should be able to run <code>esptool.py -h</code> to see a summary of all available commands, command line options and verify the installation</p></li><li><p>Download the bootloader, boot_app0 and the binary for your board from the respective links <a href="#esp32">above</a></p></li><li><p>Use the below command to upload the binary files to the board (change file names and serial port as needed, for Windows use port number e.g.: <code>COM4</code>):</p><pre><code>esptool.py --port /dev/ttyUSB0 --chip esp32 --baud 921600 --before default_reset --after hard_reset write_flash -z --flash_mode dout --flash_size detect 0xe000 boot_app0.bin 0x1000 bootloader_dio_80m.bin 0x8000 esp32dev-ble-cont-partitions.bin 0x10000 esp32dev-ble-cont-firmware.bin
</code></pre></li><li><p>Output for a successful upload should look like this:</p><pre><code>esptool.py v2.8
Serial port /dev/ttyUSB0
Connecting.....
Chip is ESP32D0WDQ6 (revision 1)
Features: WiFi, BT, Dual Core, 240MHz, VRef calibration in efuse, Coding Scheme None
Crystal is 40MHz
MAC: 30:ae:a4:ff:48:14
Uploading stub...
Running stub...
Stub running...
Changing baud rate to 921600
Changed.
Configuring flash size...
Auto-detected Flash size: 4MB
Compressed 8192 bytes to 47...
Wrote 8192 bytes (47 compressed) at 0x0000e000 in 0.0 seconds (effective 15741.5 kbit/s)...
Hash of data verified.
Flash params set to 0x0320
Compressed 17312 bytes to 11972...
Wrote 17312 bytes (11972 compressed) at 0x00001000 in 0.2 seconds (effective 903.1 kbit/s)...
Hash of data verified.
Compressed 3072 bytes to 129...
Wrote 3072 bytes (129 compressed) at 0x00008000 in 0.0 seconds (effective 5168.4 kbit/s)...
Hash of data verified.
Compressed 1444624 bytes to 838880...
Wrote 1444624 bytes (838880 compressed) at 0x00010000 in 13.1 seconds (effective 881.2 kbit/s)...
Hash of data verified.

Leaving...
Hard resetting via RTS pin...
</code></pre></li><li><p>The board resets after the upload and boots the gateway firmware</p></li></ul><h3 id="mac-esptool-py" tabindex="-1">Mac - esptool.py <a class="header-anchor" href="#mac-esptool-py" aria-label="Permalink to &quot;Mac - esptool.py&quot;">​</a></h3><p>The approach for Mac is similiar to Linux. You need to install <a href="https://brew.sh" target="_blank" rel="noreferrer">Brew</a> for Mac to use <a href="https://docs.brew.sh/Homebrew-and-Python" target="_blank" rel="noreferrer">pip</a>. The esptool.py tool needs to be adressed explicitly with .py at the end. If you do fail with the command, run <code>esptool.py chip_id</code> to let your Mac check for the ESP32 on your serial ports. A common failure for this looks like this:</p><pre><code>  A fatal error occurred: Unable to verify flash chip connection (Invalid head of packet (0xE0): Possible serial noise or corruption.).
</code></pre><p>If you receive this error</p><pre><code>  A fatal error occurred: Unable to verify flash chip connection (Packet content transfer stopped (received 7 bytes)).
</code></pre><p>while flashing, try to reduce the baud rate to <code>--baud 115200</code>, as this seems to help in most cases.</p><h2 id="esp8266" tabindex="-1">ESP8266 <a class="header-anchor" href="#esp8266" aria-label="Permalink to &quot;ESP8266&quot;">​</a></h2><ul><li>Download the NodeMCU Py Flasher tool : <a href="https://github.com/marcelstoer/nodemcu-pyflasher/releases" target="_blank" rel="noreferrer">https://github.com/marcelstoer/nodemcu-pyflasher/releases</a></li><li>Execute <code>NodeMCU-PyFlasher</code></li><li>Set the files and parameters as below: <img src="`+n+'" alt="NodeMCU Py Flasher"></li><li>Connect your board and select the COM port</li><li>Click on <em>FlashNodeMCU</em> The upload details appears.</li></ul><p>With an ESP if you did not set your network and MQTT parameters manually you can now open the <a href="./portal.html">web portal configuration</a>.</p><p>Note that to reset the wifi and MQTT settings you can check <em>yes, wipes all data</em></p><p><a href="https://hits.seeyoufarm.com" target="_blank" rel="noreferrer"><img src="https://hits.seeyoufarm.com/api/count/incr/badge.svg?url=https%3A%2F%2Fdocs.openmqttgateway.com%2Fupload%2Fbinaries.html&amp;count_bg=%2379C83D&amp;title_bg=%23555555&amp;icon=&amp;icon_color=%23E7E7E7&amp;title=hits&amp;edge_flat=false" alt="Hits"></a></p>',19)])])}const y=o(l,[["render",p]]);export{m as __pageData,y as default};
